={
  "query": "select c.id as call_log_id, c.lead_id, c.agent_id, c.duration_seconds, c.outcome, c.tpmo_disclaimer_given from call_logs c where c.created_at >= now() - interval '24 hours' and c.outcome in ('connected','appointment_set','sold') and c.tpmo_disclaimer_given = false;"
}

={
  "query": "select c.id as call_log_id, c.lead_id, c.duration_seconds from call_logs c left join recordings r on r.call_log_id = c.id where c.created_at >= now() - interval '24 hours' and c.outcome in ('connected','appointment_set','sold') and r.id is null;"
}

={
  "query": "select id from leads where opt_out=true and updated_at >= now() - interval '24 hours' and exists (select 1 from call_logs c where c.lead_id = leads.id and c.started_at > leads.opt_out_at);"
}

={
  "query": "select l.id from leads l where exists (select 1 from call_logs c where c.lead_id=l.id and c.created_at >= now()-interval '24 hours' and not exists (select 1 from agent_licenses al where al.agent_id = c.agent_id and al.state = l.state and al.active and al.expires_at > now()));"
}

={
  "query": "select lead_id, fn_check_tpmo_consent_integrity(lead_id) ok from consent_logs where consent_type='multi_tpmo_share' and created_at >= now()-interval '7 days' group by lead_id;"
}

parameters.functionCode:
const tpmo = $input.itemMatching(0)?.json || [];
const rec  = $input.itemMatching(1)?.json || [];
const leak = $input.itemMatching(2)?.json || [];
const unlic= $input.itemMatching(3)?.json || [];
const mt   = $input.itemMatching(4)?.json || [];
const mtFails = mt.filter(r => r.ok === false);
const summary = {
  missing_tpmo_disclaimer: tpmo.length,
  missing_recordings: rec.length,
  opt_out_leaks: leak.length,
  unlicensed_outreach: unlic.length,
  multi_tpmo_failures: mtFails.length,
  generated_at: new Date().toISOString()
};
const rows = [];
for (const r of tpmo) rows.push({event:'tpmo_missing', call_log_id:r.call_log_id, lead_id:r.lead_id, agent_id:r.agent_id});
for (const r of rec) rows.push({event:'recording_missing', call_log_id:r.call_log_id, lead_id:r.lead_id});
for (const r of leak) rows.push({event:'opt_out_leak', lead_id:r.id});
for (const r of unlic) rows.push({event:'unlicensed_outreach', lead_id:r.id});
for (const r of mtFails) rows.push({event:'multi_tpmo_consent_mismatch', lead_id:r.lead_id});
return [{json:{summary, rows}}];

